+  const rawPage = req.query.page;
+  const rawLimit = req.query.limit;
+  const rawUserId = req.query.user_id;
+
+  const page = rawPage === undefined ? DEFAULT_PAGE : positiveInteger(rawPage);
+  const limit = rawLimit === undefined ? DEFAULT_LIMIT : positiveInteger(rawLimit);
+  const userId = rawUserId === undefined ? undefined : positiveInteger(rawUserId);
+
+  if (page === undefined || limit === undefined || limit > MAX_LIMIT) {
+    res.status(400).json({ error: "page must be a positive integer and limit must be an integer between 1 and 100" });
+    return;
+  }
+  if (rawUserId !== undefined && userId === undefined) {
+    res.status(400).json({ error: "user_id must be a positive integer" });
+    return;
+  }
+
+  const effectiveUserId = userId ?? CURRENT_USER_ID;
+  const { total } = db
+    .prepare(`SELECT COUNT(*) AS total FROM items WHERE user_id = ?`)
+    .get(effectiveUserId) as { total: number };
+  const offset = (page - 1) * limit;
+  const rows = db
+    .prepare(`SELECT * FROM items WHERE user_id = ? ORDER BY id LIMIT ? OFFSET ?`)
+    .all(effectiveUserId, limit, offset) as ItemRow[];
+
+  res.json({
+    items: rows.map(toDTO),
+    pagination: {
+      page,
+      limit,
+      total,
+      total_pages: Math.ceil(total / limit),
+    },
+  });
 }

